const nodes: string[] = data.nodes;
const edges: Array<{ from: string; to: string; weight: number }> = data.edges;

const adj: Record<string, Array<{ to: string; weight: number }>> = {};
for (let i = 0; i < nodes.length; i++) {
  adj[nodes[i]] = [];
}
for (let i = 0; i < edges.length; i++) {
  const e = edges[i];
  const from = e.from;
  const to = e.to;
  const weight = Number(e.weight);
  if (!adj[from]) adj[from] = [];
  if (!adj[to]) adj[to] = [];
  adj[from].push({ to, weight });
  adj[to].push({ to: from, weight });
}

const start = 'A';
const dist: Record<string, number> = {};
for (let i = 0; i < nodes.length; i++) {
  dist[nodes[i]] = Infinity;
}
dist[start] = 0;
const visited: Record<string, boolean> = {};
for (let i = 0; i < nodes.length; i++) {
  visited[nodes[i]] = false;
}

while (true) {
  let current: string | null = null;
  let best = Infinity;
  for (let i = 0; i < nodes.length; i++) {
    const n = nodes[i];
    const d = dist[n];
    if (!visited[n] && d < best) {
      best = d;
      current = n;
    }
  }
  if (current === null) break;
  visited[current] = true;
  const currentDist = dist[current];
  const neighbors = adj[current] || [];
  for (let j = 0; j < neighbors.length; j++) {
    const e = neighbors[j];
    const newDist = currentDist + e.weight;
    if (newDist < dist[e.to]) {
      dist[e.to] = newDist;
    }
  }
}

