function countLines(buffer: Buffer): number {
  if (buffer.length === 0) return 0;
  const text = buffer.toString('utf8');
  const normalized = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  if (normalized === '') return 0;
  const parts = normalized.split('\n');
  let lines = parts.length;
  if (normalized.charAt(normalized.length - 1) === '\n') {
    lines -= 1;
  }
  return lines;
}

function walk(dir: string, root: string, files: FileInfo[]): void {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isSymbolicLink()) continue;
    if (entry.isDirectory()) {
      walk(fullPath, root, files);
    } else if (entry.isFile()) {
      const buffer = fs.readFileSync(fullPath);
      const rel = path.relative(root, fullPath).split(path.sep).join('/');
      files.push({
        relativePath: rel,
        lines: countLines(buffer),
        chars: buffer.length,
      });
    }
  }
}

