static char *read_output(const char *cmd, size_t *len) {
    FILE *fp = popen(cmd, "r");
    if (!fp) { *len = 0; return NULL; }
    size_t cap = 128;
    size_t size = 0;
    char *buf = malloc(cap);
    if (!buf) { pclose(fp); *len = 0; return NULL; }
    char temp[256];
    while (fgets(temp, sizeof(temp), fp)) {
        size_t tlen = strlen(temp);
        if (size + tlen + 1 > cap) {
            cap *= 2;
            char *tmp = realloc(buf, cap);
            if (!tmp) { free(buf); pclose(fp); *len = 0; return NULL; }
            buf = tmp;
        }
        memcpy(buf + size, temp, tlen);
        size += tlen;
    }
    if (size + 1 > cap) {
        cap = size + 1;
        char *tmp = realloc(buf, cap);
        if (!tmp) { free(buf); pclose(fp); *len = 0; return NULL; }
        buf = tmp;
    }
    buf[size] = '\0';
    pclose(fp);
    *len = size;
    return buf;
}

static void trim_trailing(char *s, size_t *len) {
    while (*len > 0 && isspace((unsigned char)s[*len - 1])) {
        s[--(*len)] = '\0';
    }
}

