function multiply(X: number[][], Y: number[][]): number[][] {
  const n = X.length;
  const m = Y[0].length;
  const p = Y.length;
  const result: number[][] = [];
  for (let i = 0; i < n; i++) {
    const row: number[] = [];
    for (let j = 0; j < m; j++) {
      let sum = 0;
      for (let k = 0; k < p; k++) {
        sum += X[i][k] * Y[k][j];
      }
      row.push(sum);
    }
    result.push(row);
  }
  return result;
}

function determinant(M: number[][]): number {
  const a = M[0][0], b = M[0][1], c = M[0][2];
  const d = M[1][0], e = M[1][1], f = M[1][2];
  const g = M[2][0], h = M[2][1], i = M[2][2];
  return a * (e * i - f * h) - b * (d * i - f * g) + c * (d * h - e * g);
}

const C = multiply(A, B);

function formatMatrix(M: number[][]): string[] {
  return M.map(row => {
    const formatted = row.map(v => {
      const s = String(v);
      let padded = "";
      for (let i = s.length; i < 4; i++) {
        padded += " ";
      }
      return padded + s;
    });
    return "  " + formatted.join(" ");
  });
}

