func formatRow(_ row: [Int]) -> String {
    let fields = row.map { value -> String in
        let s = "\(value)"
        let padding = 4 - s.count
        return String(repeating: " ", count: padding) + s
    }
    return "  " + fields.joined(separator: " ")
}

func matrixMultiply(_ A: [[Int]], _ B: [[Int]]) -> [[Int]] {
    let n = A.count
    let m = B[0].count
    let p = B.count
    var C = [[Int]](repeating: [Int](repeating: 0, count: m), count: n)
    for i in 0..<n {
        for j in 0..<m {
            var sum = 0
            for k in 0..<p {
                sum += A[i][k] * B[k][j]
            }
            C[i][j] = sum
        }
    }
    return C
}

func determinant(_ M: [[Int]]) -> Int {
    let n = M.count
    if n == 1 {
        return M[0][0]
    }
    if n == 2 {
        return M[0][0] * M[1][1] - M[0][1] * M[1][0]
    }
    var det = 0
    for col in 0..<n {
        var submatrix = [[Int]]()
        for i in 1..<n {
            var row = [Int]()
            for j in 0..<n {
                if j != col {
                    row.append(M[i][j])
                }
            }
            submatrix.append(row)
        }
        det += ((col % 2 == 0) ? 1 : -1) * M[0][col] * determinant(submatrix)
    }
    return det
}

